// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8,
  'grow-magenta': 0xE040FB,
  'plant-green': 0x5A9E58,
  'ice-pale': 0xD8EEF8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'climate-dial',
  role: 'prop',
  reference: 'models and assets images/climate-dial.webp'
};

async function build() {
  const root = createRoot('climate-dial');
  defineBudget({ triangles: BUDGETS['small-prop'] }, root);

  const m = styleMaterials();

  const W = 0.26; // total width along Z (-0.13 to +0.13)
  const H = 0.26; // total height along Y (0 to 0.26)
  const D = 0.052; // body depth along X (0 to 0.052)
  const c = 0.038; // corner chamfer
  const centerY = H / 2; // 0.13

  // 1. Octagonal Housing Profile in (u, v) where u = -Z, v = Y - centerY
  // Axis x: (d, v, -u) -> X = d, Y = v + centerY, Z = -u
  const halfW = W / 2;
  const halfH = H / 2;

  const housingProfile = [
    [-halfW + c, halfH],
    [halfW - c, halfH],
    [halfW, halfH - c],
    [halfW, -halfH + c],
    [halfW - c, -halfH],
    [-halfW + c, -halfH],
    [-halfW, -halfH + c],
    [-halfW, halfH - c]
  ];

  // Ivory outer body shell
  const bodyGeo = await extrudeProfile(housingProfile, {
    depth: D,
    axis: 'x',
    center: false
  });
  createPart('HousingBody', bodyGeo, m.panel, {
    parent: root,
    position: [0, centerY, 0]
  });

  // Top orange accent strip
  const topAccentGeo = boxGeo(0.034, 0.008, 0.14);
  createPart('TopAccent', topAccentGeo, m.accent, {
    parent: root,
    position: [D * 0.5, H + 0.004, 0]
  });

  // Left & right side orange accent strips
  const sideAccentGeo = boxGeo(0.034, 0.12, 0.008);
  createPart('SideAccentL', sideAccentGeo, m.accent, {
    parent: root,
    position: [D * 0.5, centerY, halfW + 0.004] // Screen-left (+Z)
  });
  createPart('SideAccentR', sideAccentGeo, m.accent, {
    parent: root,
    position: [D * 0.5, centerY, -halfW - 0.004] // Screen-right (-Z)
  });

  // 2. Bezel and Faceplate
  // Slate outer bezel frame
  const bW = 0.20;
  const bH = 0.20;
  const bc = 0.032;
  const bezelProfile = [
    [-bW / 2 + bc, bH / 2],
    [bW / 2 - bc, bH / 2],
    [bW / 2, bH / 2 - bc],
    [bW / 2, -bH / 2 + bc],
    [bW / 2 - bc, -bH / 2],
    [-bW / 2 + bc, -bH / 2],
    [-bW / 2, -bH / 2 + bc],
    [-bW / 2, bH / 2 - bc]
  ];

  const bezelGeo = await extrudeProfile(bezelProfile, {
    depth: 0.008,
    axis: 'x',
    center: false
  });
  createPart('InnerBezel', bezelGeo, m.panelGray, {
    parent: root,
    position: [D, centerY, 0]
  });

  // Dark slate dial faceplate
  const fW = 0.184;
  const fH = 0.184;
  const fc = 0.028;
  const faceProfile = [
    [-fW / 2 + fc, fH / 2],
    [fW / 2 - fc, fH / 2],
    [fW / 2, fH / 2 - fc],
    [fW / 2, -fH / 2 + fc],
    [fW / 2 - fc, -fH / 2],
    [-fW / 2 + fc, -fH / 2],
    [-fW / 2, -fH / 2 + fc],
    [-fW / 2, fH / 2 - fc]
  ];
  const faceGeo = await extrudeProfile(faceProfile, {
    depth: 0.004,
    axis: 'x',
    center: false
  });
  const faceplateNode = createPivot('faceplate', [D + 0.003, centerY, 0], root);
  createPart('DialFace', faceGeo, m.trim, {
    parent: faceplateNode,
    position: [0, 0, 0]
  });

  // 3. Four corner mounting bolts (on ivory chamfer corners)
  const boltR = 0.011;
  const boltH = 0.006;
  const boltGeo = cylinderGeo(boltR, boltR, boltH, 6);
  const boltSlotGeo = boxGeo(0.007, 0.002, 0.016);
  const boltMat = m.panelGray;
  const slotMat = m.trim;

  const boltCoords = [
    [halfW - 0.024, halfH - 0.024],
    [-halfW + 0.024, halfH - 0.024],
    [halfW - 0.024, -halfH + 0.024],
    [-halfW + 0.024, -halfH + 0.024]
  ];

  for (let i = 0; i < boltCoords.length; i++) {
    const [bz, by] = boltCoords[i];
    const boltMesh = createPart(`CornerBolt_${i}`, boltGeo, boltMat, {
      parent: root,
      position: [D + 0.002, centerY + by, bz],
      rotation: [0, 0, 90]
    });
    createPart(`CornerBoltSlot_${i}`, boltSlotGeo, slotMat, {
      parent: boltMesh,
      position: [0.003, 0, 0]
    });
  }

  // 4. Scale markings on faceplate (arc and ticks for 12, 16, 20)
  // Looking at front face: +Z is screen-left (12), -Z is screen-right (20)
  const arcRadius = 0.062;
  const faceX = 0.0045;
  const gaugeMarkingsNode = createPivot('gauge_markings', [faceX, 0, 0], faceplateNode);

  const arcSegments = 16;
  const minAngle = -Math.PI * 0.28;
  const maxAngle = Math.PI * 0.28;
  const angleStep = (maxAngle - minAngle) / arcSegments;
  const segLen = (maxAngle - minAngle) * arcRadius / arcSegments * 1.05;

  for (let s = 0; s < arcSegments; s++) {
    const a = minAngle + (s + 0.5) * angleStep;
    const segY = Math.cos(a) * arcRadius;
    const segZ = Math.sin(a) * arcRadius; // a < 0 -> screen-right (-Z), a > 0 -> screen-left (+Z)
    const segGeo = boxGeo(0.0015, segLen, 0.0035);
    createPart(`ArcSeg_${s}`, segGeo, m.panel, {
      parent: gaugeMarkingsNode,
      position: [0, segY, segZ],
      rotation: [-a * 180 / Math.PI, 0, 0]
    });
  }

  // Radial tick marks at 12 (+45° / screen-left), 16 (0° / top), 20 (-45° / screen-right)
  const tickAngles = [
    { a: Math.PI * 0.25, name: 'Tick12' },
    { a: 0, name: 'Tick16' },
    { a: -Math.PI * 0.25, name: 'Tick20' }
  ];

  const tickGeo = boxGeo(0.002, 0.012, 0.004);
  for (const { a, name } of tickAngles) {
    const tY = Math.cos(a) * (arcRadius + 0.005);
    const tZ = Math.sin(a) * (arcRadius + 0.005);
    createPart(name, tickGeo, m.panel, {
      parent: gaugeMarkingsNode,
      position: [0, tY, tZ],
      rotation: [-a * 180 / Math.PI, 0, 0]
    });
  }

  // Digits:
  // On screen: Left is +Z, Right is -Z
  const segW = 0.0022;
  const segThick = 0.002;
  function addSeg(name, y, z, len, isVertical) {
    const g = isVertical ? boxGeo(segThick, len, segW) : boxGeo(segThick, segW, len);
    createPart(name, g, m.panel, {
      parent: gaugeMarkingsNode,
      position: [0, y, z]
    });
  }

  // Top digit "16" around Y = 0.082, Z = 0
  // '1' is on screen-left (+Z):
  addSeg('Digit16_1', 0.082, 0.007, 0.016, true);
  // '6' is on screen-right (-Z):
  addSeg('Digit16_6_top', 0.089, -0.007, 0.009, false);
  addSeg('Digit16_6_l', 0.082, -0.003, 0.016, true);
  addSeg('Digit16_6_mid', 0.082, -0.007, 0.009, false);
  addSeg('Digit16_6_bot', 0.075, -0.007, 0.009, false);
  addSeg('Digit16_6_r', 0.078, -0.011, 0.008, true);

  // Screen-left digit "12" around Y = 0.052, Z = +0.065
  // '1' is on screen-left (+Z = +0.072):
  addSeg('Digit12_1', 0.052, 0.072, 0.016, true);
  // '2' is on screen-right (+Z = +0.058):
  addSeg('Digit12_2_top', 0.059, 0.058, 0.009, false);
  addSeg('Digit12_2_r', 0.056, 0.054, 0.008, true);
  addSeg('Digit12_2_mid', 0.052, 0.058, 0.009, false);
  addSeg('Digit12_2_l', 0.048, 0.062, 0.008, true);
  addSeg('Digit12_2_bot', 0.044, 0.058, 0.009, false);

  // Screen-right digit "20" around Y = 0.052, Z = -0.065
  // '2' is on screen-left (-Z = -0.058):
  addSeg('Digit20_2_top', 0.059, -0.058, 0.009, false);
  addSeg('Digit20_2_r', 0.056, -0.062, 0.008, true);
  addSeg('Digit20_2_mid', 0.052, -0.058, 0.009, false);
  addSeg('Digit20_2_l', 0.048, -0.054, 0.008, true);
  addSeg('Digit20_2_bot', 0.044, -0.058, 0.009, false);
  // '0' is on screen-right (-Z = -0.072):
  addSeg('Digit20_0_top', 0.059, -0.072, 0.009, false);
  addSeg('Digit20_0_bot', 0.044, -0.072, 0.009, false);
  addSeg('Digit20_0_l', 0.052, -0.068, 0.016, true);
  addSeg('Digit20_0_r', 0.052, -0.076, 0.016, true);

  // 5. Status Indicator LED (bottom-right of faceplate: screen-right is -Z)
  const ledNode = createPivot('led_indicator', [0, -0.058, -0.058], faceplateNode);
  const ledBezelGeo = cylinderGeo(0.008, 0.008, 0.004, 12);
  createPart('LedBezel', ledBezelGeo, m.trim, {
    parent: ledNode,
    position: [0.002, 0, 0],
    rotation: [0, 0, 90]
  });
  const ledLensGeo = cylinderGeo(0.005, 0.005, 0.005, 12);
  createPart('LedLens', ledLensGeo, m.glowWarm, {
    parent: ledNode,
    position: [0.003, 0, 0],
    rotation: [0, 0, 90]
  });

  // 6. Central Rotary Knob (semantic node 'knob')
  const knobNode = createPivot('knob', [D + 0.007, centerY, 0], root);

  // Knob collar
  const collarGeo = cylinderGeo(0.046, 0.046, 0.006, 12);
  createPart('KnobCollar', collarGeo, m.accent, {
    parent: knobNode,
    position: [0.003, 0, 0],
    rotation: [0, 0, 90]
  });

  // Faceted 10-sided main knob prism
  const knobBodyGeo = cylinderGeo(0.042, 0.042, 0.024, 10);
  createPart('KnobBody', knobBodyGeo, m.accent, {
    parent: knobNode,
    position: [0.018, 0, 0],
    rotation: [0, 0, 90]
  });

  // Chamfered front rim cap
  const knobCapGeo = cylinderGeo(0.038, 0.038, 0.008, 10);
  createPart('KnobCap', knobCapGeo, m.accent, {
    parent: knobNode,
    position: [0.032, 0, 0],
    rotation: [0, 0, 90]
  });

  // Ivory Pointer Needle pointing towards top (16)
  const needleProfile = [
    [-0.005, 0],
    [0.005, 0],
    [0.002, 0.028],
    [-0.002, 0.028]
  ];
  const needleGeo = await extrudeProfile(needleProfile, {
    depth: 0.006,
    axis: 'x',
    center: false
  });
  createPart('KnobNeedle', needleGeo, m.panel, {
    parent: knobNode,
    position: [0.032, 0.008, 0]
  });

  return root;
}
